// Generate the pattern pages, the glossary pages, and the website data bundle
// from the files in data/.
//
//   node scripts/build.mjs          write every generated file
//   node scripts/build.mjs --check  fail if any generated file is out of date
//
// Generated files are committed so that they read well on GitHub, and the check
// mode runs in CI so that they can never drift from the data.

import fs from 'node:fs';
import path from 'node:path';
import { loadBundle, readDiagram, root } from './lib/load.mjs';

